import { edit_orders } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    ViewOrderDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      pendingtoPay: false,
      finalAmount: "",
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.pendingtoPay = false;
    },
    is_number(evt, value) {
      evt = evt || window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      }
      if (value.length >= 14 && charCode >= 48 && charCode <= 57) {
        evt.preventDefault();
      }
    },
    verify_close() {
      const shouldShowTextField = this.pendingtoPay && (this.rowInfo.remaining_amount !== 0 || this.rowInfo.remaining_amount === undefined);
      if (shouldShowTextField) {
        if (this.$refs.form.validate()) {
          this.Close_Order();
        }
      } else {
        this.Close_Order();
      }
    },
    async Close_Order() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_orders, {
          input: {
            order_id: this.rowInfo.order_id,
            order_delevery_status: "DELEVERED",
            final_received_amount: this.pendingtoPay === true ? this.finalAmount : this.rowInfo.total_amount
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_orders);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
